from seven_desks.settings import CACHE as BUILD_ROOT, LAKE, SOURCE as REVIEW_SOURCE, FROZEN_VERSION
from seven_desks.store import version_root, connect
"""Offline entity details, source-unit alignment and calendar-aligned chart overlays."""
from pathlib import Path
import duckdb
import sys
P=Path(__file__).resolve().parents[2];OUT=(BUILD_ROOT / 'owners');L=LAKE;S=L/'meta/review/seven-followup-20261113/owners'
c=connect(config={'threads':2,'memory_limit':'4GB'});c.execute('SET preserve_insertion_order=false')
for folder,prefix in [(S,''),(OUT,'l_')]:
 for p in folder.glob('*.parquet'):
  if p.name.startswith(('_','tmp_')):continue
  c.execute(f"CREATE VIEW {prefix+p.stem} AS SELECT * FROM read_parquet('{p}')")
def raw(n):
 p=next(L/l/n for l in ['curated','derived'] if (L/l/n).exists());c.execute(f"CREATE VIEW r_{n} AS SELECT * FROM read_parquet('{p}/**/*.parquet',hive_partitioning=false,union_by_name=true)")
def emit(n,sql):
 p=OUT/(n+'.parquet');tmp=p.with_suffix('.tmp');
 if len(sys.argv)>1 and n not in sys.argv[1].split(','):return
 c.execute(f"COPY ({sql}) TO '{tmp}' (FORMAT PARQUET,COMPRESSION ZSTD)");tmp.replace(p);c.execute(f"CREATE OR REPLACE VIEW l_{n} AS SELECT * FROM read_parquet('{p}')");print(n,c.execute(f'SELECT count(*) FROM l_{n}').fetchone()[0],flush=True)
for n in ['fund_manager_tenures','instruments','daily_bars','adj_factors','index_bars','moneyflow','stock_moneyflow_ths']:raw(n)
emit('stock_lifetimes',"SELECT symbol,list_date,delist_date FROM r_instruments WHERE asset_type='stock' QUALIFY row_number() OVER(PARTITION BY symbol ORDER BY fetched_at DESC)=1")
emit('fund_stock_managers',"""SELECT h.holding_symbol symbol,h.report_period,count(DISTINCT m.manager_name) active_manager_name_count FROM fund_holdings_pit h JOIN r_fund_manager_tenures m ON m.fund_symbol=h.fund_symbol AND m.begin_date<=h.report_period AND (m.end_date IS NULL OR m.end_date>=h.report_period) AND (m.announce_date IS NULL OR m.announce_date<=DATE '2026-11-09') GROUP BY ALL""")
emit('company_holding_universe',"""SELECT * FROM l_company_holding_complete UNION ALL BY NAME SELECT c.entity_id company_id,c.report_period,c.symbol,0.0 shares,0.0 market_value,0::BIGINT fund_count,0::BIGINT value_count,0::BIGINT row_count,NULL::DATE latest_announce,'exit_from_comparable_visible_full_holdings' disclosure_scope,c.close,s.factor,s.adjusted_close,s.price_date,s.industry_code,s.industry_name,s.float_shares,0.0 float_holding_ratio,0.0 weight,NULL::BIGINT holding_rank,'verified_comparable_visible_exit_not_actual_liquidation' quality_status,n.name,c.change_status,c.share_change_ratio,c.estimated_change_value,0::BIGINT consecutive_halfyears,-b.weight influence_pp,r.post_period_return FROM company_changes c LEFT JOIN period_stock_context s USING(symbol,report_period) LEFT JOIN company_stock_holdings b ON b.company_id=c.entity_id AND b.symbol=c.symbol AND b.report_period=c.prev_period LEFT JOIN l_stock_period_returns r ON r.symbol=c.symbol AND r.report_period=c.report_period LEFT JOIN l_names n ON n.symbol=c.symbol WHERE c.change_status='exit_visible'""")
emit('etf_period_asof',"""SELECT symbol,trade_date,name,category,cast(date_trunc('week',trade_date) AS DATE) week_start,cast(date_trunc('quarter',trade_date) AS DATE) quarter_start,sum(net_subscription) OVER ww week_net_subscription,sum(net_subscription) OVER wq quarter_net_subscription,count(net_subscription) OVER ww week_valid_days,count(*) OVER ww week_observed_days,count(net_subscription) OVER wq quarter_valid_days,count(*) OVER wq quarter_observed_days FROM etf_daily_flow WINDOW ww AS(PARTITION BY symbol,date_trunc('week',trade_date) ORDER BY trade_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW),wq AS(PARTITION BY symbol,date_trunc('quarter',trade_date) ORDER BY trade_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)""")
emit('stock_three_sources_cny',"""SELECT symbol,trade_date,'moneyflow' provider,net_mf_amount net_flow_native,net_mf_amount*10000 net_flow_cny,'万元' source_unit,'CNY' display_unit FROM r_moneyflow WHERE trade_date BETWEEN DATE '2016-01-01' AND DATE '2026-11-09' UNION ALL SELECT symbol,trade_date,'stock_moneyflow_ths',net_amount,net_amount,'元','CNY' FROM r_stock_moneyflow_ths WHERE trade_date BETWEEN DATE '2016-01-01' AND DATE '2026-11-09' UNION ALL SELECT symbol,trade_date,'fund_flow',main_net_inflow,main_net_inflow,'元','CNY' FROM stock_fund_flow_windows WHERE trade_date BETWEEN DATE '2016-01-01' AND DATE '2026-11-09'""")
c.execute("CREATE TEMP VIEW prices AS SELECT b.symbol,b.trade_date,b.close*f.factor adjusted_close FROM r_daily_bars b LEFT JOIN r_adj_factors f ON b.symbol=f.symbol AND b.trade_date=f.trade_date AND f.adjust_type='hfq' WHERE b.trade_date BETWEEN DATE '2016-01-01' AND DATE '2026-11-09'")
c.execute("CREATE TEMP VIEW bench AS SELECT trade_date,close FROM r_index_bars WHERE symbol='000300.SH' AND frequency='1d' AND trade_date<=DATE '2026-11-09'")
emit('fund_consensus_following_complete',"""WITH x AS(SELECT f.report_period,f.consensus,f.symbol,p.adjusted_close start_price,last_day(f.report_period+INTERVAL '6 months') end_date FROM fund_stock_crowding f LEFT JOIN l_stock_lifetimes life USING(symbol) LEFT JOIN period_stock_context p USING(symbol,report_period) WHERE f.consensus IN('buy','sell') AND (life.list_date IS NULL OR life.list_date<=last_day(f.report_period-INTERVAL '6 months')) AND last_day(f.report_period+INTERVAL '6 months')<=DATE '2026-11-09'),r AS(SELECT x.*,b.adjusted_close end_price FROM x ASOF LEFT JOIN prices b ON x.symbol=b.symbol AND x.end_date>=b.trade_date),a AS(SELECT report_period,consensus,end_date,avg(end_price/nullif(start_price,0)-1) equal_weight_following_return,count(end_price/nullif(start_price,0)) valid_price_count,count(*) signal_stock_count FROM r GROUP BY ALL),b AS(SELECT a.*,bs.close begin_benchmark FROM a ASOF LEFT JOIN bench bs ON a.report_period>=bs.trade_date) SELECT b.*,be.close/nullif(begin_benchmark,0)-1 benchmark_return FROM b ASOF LEFT JOIN bench be ON b.end_date>=be.trade_date""")
c.close()
